  ('209d0465-d258-4898-9f17-db0c7d19458d', $$Biologie$$, $$VWO$$, $$Kleurpatroon van de kleine monarchvlinder$$, $$VWO Biologie 2023-II$$),
  ('00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$Biologie$$, $$VWO$$, $$Onderzoek naar medicijnen tegen ebola$$, $$VWO Biologie 2023-II$$),
  ('5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$Biologie$$, $$VWO$$, $$Strijden tegen Striga$$, $$VWO Biologie 2023-II$$),
  ('ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$Biologie$$, $$VWO$$, $$Nieuwe behandelmethodes voor sikkelcelanemie$$, $$VWO Biologie 2023-II$$),
