insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('516fd896-23d4-433e-98cc-0176f188a92b', '209d0465-d258-4898-9f17-db0c7d19458d', $$inleiding: kleurpatroon vleugels gekoppeld aan geslacht in contactzone$$,
   $$biologie-vwo-2023-ii-kleurpatroon-van-de-kleine-monarchvlinder-context1.png$$,
   $$De kleine monarchvlinder is een vlindersoort waarbij veel variatie aanwezig is in het kleurpatroon van de vleugels. In één gebied in Afrika is het kleurpatroon gekoppeld aan het geslacht. Onderzoekers hebben aangetoond dat deze koppeling wordt veroorzaakt door een chromosoommutatie én een bacterie.$$, 'inline'),
  ('ed841d18-35c0-4b23-a002-5e503d237140', '209d0465-d258-4898-9f17-db0c7d19458d', $$vier ondersoorten en contactzone; genen A, B, G op de chromosomen (afbeelding 1)$$,
   $$biologie-vwo-2023-ii-kleurpatroon-van-de-kleine-monarchvlinder-context2.png$$,
   $$Van de kleine monarchvlinder (Danaus chrysippus) zijn vier ondersoorten bekend (D. c. alcippus, D. c. chrysippus, D. c. dorippus en D. c. orientis), die in Afrika en delen van Azië voorkomen. In Oost-Afrika overlappen de leefgebieden en kunnen de vlinders zich onderling voortplanten.
afbeelding 1 Alleen in deze contactzone (het omlijnde gebied in afbeelding 1) blijkt het kleurpatroon van de voorvleugels gekoppeld te zijn aan het geslacht. Bij de kleine monarchvlinder wordt het kleurpatroon van de vleugels bepaald door drie genen:
− gen A op chromosoom 4
− gen B op chromosoom 15
− gen G op chromosoom 15$$, 'inline'),
  ('553f6995-176a-47f3-aeae-a33164025e55', '209d0465-d258-4898-9f17-db0c7d19458d', $$genen A, B en G coderen voor kleurkenmerken; drie fenotypen$$,
   $$biologie-vwo-2023-ii-kleurpatroon-van-de-kleine-monarchvlinder-context3.png$$,
   $$Deze drie genen coderen voor de intensiteit van de oranje kleur (donker of licht), voor een zwarte vleugeltip op de voorvleugel (groot of klein) en voor een witte vlek op de achtervleugel (wel of geen). In de afbeelding is het oranje deel van de vleugels met licht- of donkergrijs aangegeven. Drie fenotypen zijn:
1 een grote zwarte vleugeltip op de voorvleugel
2 een witte vlek op de achtervleugel
3 een donker oranje kleur$$, 'inline'),
  ('530fb7cb-a58a-4676-87f2-53b2978a0ce1', '209d0465-d258-4898-9f17-db0c7d19458d', $$uitspraken over reproductieve isolatie, allopatrische soortvorming en gene flow$$,
   $$biologie-vwo-2023-ii-kleurpatroon-van-de-kleine-monarchvlinder-context4.png$$,
   $$Over de monarchvlinders in de contactzone worden de volgende uitspraken gedaan:
1 Er is reproductieve isolatie tussen de ondersoorten.
2 Er treedt allopatrische soortvorming op.
3 Er vindt gene flow plaats.$$, 'inline'),
  ('40d1f205-f3e9-4a1f-8260-1f1ae166361b', '209d0465-d258-4898-9f17-db0c7d19458d', $$genotypen van twee vlinders uit de contactzone (afbeelding 2); gekoppelde genen B en G$$,
   $$biologie-vwo-2023-ii-kleurpatroon-van-de-kleine-monarchvlinder-context5.png$$,
   $$In afbeelding 2 zijn twee genotypen van vlinders uit de contactzone met de bijbehorende fenotypen weergegeven.
afbeelding 2
De genen B en G liggen zo dicht bij elkaar, dat ze vrijwel altijd gekoppeld overerven.$$, 'inline'),
  ('89e61d19-266c-4df8-bb5b-25c958c1cc05', '209d0465-d258-4898-9f17-db0c7d19458d', $$W/Z-geslachtschromosomen, neo-W-chromosoom en Spiroplasma-bacterie (afbeelding 3, afbeelding 4)$$,
   $$biologie-vwo-2023-ii-kleurpatroon-van-de-kleine-monarchvlinder-context6.png$$,
   $$Bij vlinders komen de geslachtschromosomen W en Z voor. Vrouwtjes hebben WZ, mannetjes ZZ. Bij vlinders die permanent in de contactzone verblijven, is het W-geslachtschromosoom echter gefuseerd met chromosoom 15. Dit gefuseerde chromosoom wordt het neo-W-chromosoom genoemd. Het is ongeveer 2200 jaar geleden ontstaan en wordt telkens onveranderd doorgegeven aan het nageslacht. Onderzoekers hebben aangetoond dat in dezelfde periode dat het neo-W-chromosoom ontstond, de kleine monarchvlinder in dit gebied ook geïnfecteerd is geraakt met een Spiroplasma-bacterie. Deze bacterie is aanwezig in alle cellen van de vlinder en wordt via de eicel doorgegeven. De bacterie is dodelijk voor mannelijke rupsen en komt daardoor uitsluitend voor bij vrouwelijke vlinders met het neo-W-chromosoom. Vrijwel alle vrouwtjes met het neo-W-chromosoom dragen de bacterie.
In afbeelding 3 zijn een cel van een vrouwtje en een cel van een mannetje schematisch weergegeven.
afbeelding 3
In afbeelding 4 zijn vier genotypen weergegeven:
afbeelding 4$$, 'inline'),
  ('d7ef0636-1b36-4275-9fa7-cce92720988f', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$inleiding: onderzoek naar medicijnen tegen ebola-uitbraken$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context1.png$$,
   $$Tussen 2010 en 2020 vonden in Afrika twee uitbraken plaats van de zeer besmettelijke virusziekte ebola. Onderzoekers hebben een aantal medicijnen getest om de uitbraken in te dammen en toekomstige ebola- epidemieën te voorkomen.$$, 'inline'),
  ('6fc153f7-d115-4b25-807e-bae2ffa9c1fd', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$ebolavirus als negatief-sense RNA-virus; infectie en vermeerdering (afbeelding 1)$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context2.png$$,
   $$Ebola is een van de meest dodelijke virusziekten bij mensen. Het ebolavirus is een enkelstrengs RNA-virus dat van mens op mens kan worden overgedragen via lichaamsvloeistoffen. Enkelstrengs RNA-virussen worden verdeeld in twee categorieën: positief-sense en negatief-sense. Positief-sense betekent dat de virale RNA-streng de coderende basenvolgorde bevat. Negatief-sense betekent dat de virale RNA-streng een basenvolgorde heeft die complementair is aan de coderende basenvolgorde. Het ebolavirus is negatief-sense. In afbeelding 1 is de infectie en de daarop volgende stappen van de vermenigvuldiging van het ebolavirus in een menselijke cel schematisch weergegeven. Hierin is het negatief-sense RNA aangegeven met – en positief-sense met +.
afbeelding 1$$, 'inline'),
  ('30b75203-3887-4cc9-9586-0e809706d202', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$uitspraken over het ebolavirus en infectie van een menselijke cel$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context3.png$$,
   $$Over het ebolavirus en de infectie van een menselijke cel door dit virus worden de volgende uitspraken gedaan:
1 Het negatief-sense RNA wordt gebruikt als mRNA voor de productie van virale eiwitten.
2 De membraan van de virale envelop wordt gevormd uit de membraan van de gastheercel.
3 De translatie waarbij de virale membraaneiwitten worden gevormd, vindt plaats in het golgi-systeem.$$, 'inline'),
  ('c37aec8e-edeb-439a-b309-852712c6eb93', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$ebola-infectie van dendritische cellen blokkeert immuunrespons (afbeelding 2)$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context4.png$$,
   $$Het ebolavirus infecteert aanvankelijk vooral afweercellen: dendritische cellen, monocyten en macrofagen. Geïnfecteerde dendritische cellen rijpen dan niet meer, waardoor ze een aantal membraaneiwitten niet meer produceren. Als gevolg hiervan kunnen deze dendritische cellen het specifieke afweersysteem niet meer activeren. Afbeelding 2 geeft links een normale immuunrespons weer en rechts de gevolgen van een ebola- infectie.
afbeelding 2$$, 'inline'),
  ('e7938ad1-6e24-46d4-a0a7-17641adec6ee', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$leverschade en stolsels door ebola-infectie; drie eiwitten (collageen, fibrinogeen, tromboplastine)$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context5.png$$,
   $$Als virusdeeltjes vrijkomen uit de geïnfecteerde afweercellen, verspreiden ze zich naar andere organen zoals de lever. Als gevolg hiervan raakt de lever beschadigd, waardoor de productie van stollingseiwitten afneemt. Dit veroorzaakt hevige bloedingen. Een ander symptoom is de vorming van stolsels in de bloedbaan. Die ontstaan als gevolg van een ontstekingsreactie van de bloedvatwand waarbij een bepaald eiwit wordt afgegeven.
Drie eiwitten zijn: collageen, fibrinogeen en de stollingsfactor tromboplastine.$$, 'inline'),
  ('b0e33f09-b196-49ba-ad7c-e203d28ae842', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$de virusremmer remdesivir als nucleotide-analoog (afbeelding 3)$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context6.png$$,
   $$In 2016 kregen onderzoekers afbeelding 3 toestemming om de virusremmer remdesivir te testen. Dit is een nucleotide-analoog: een stof die lijkt op een bepaalde nucleotide. Deze stof verstoort de werking van het virale RNA-polymerase. Als een remdesivir- molecuul wordt ingebouwd door de virale RNA-polymerase, is verdere verlenging van dit RNA-molecuul niet mogelijk. Afbeelding 3 toont de structuurformule van remdesivir.
Een deel van het remdesivir-molecuul vertoont een grote overeenkomst met een bepaalde stikstofbase.$$, 'inline'),
  ('23802a8b-dd06-41c8-8422-6f4cbe012b4c', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$ontwikkeling van monoklonale antistoffen (mAb''s) via gefuseerde muizen- en tumorcellen (afbeelding 4)$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context7.png$$,
   $$Enkele farmaceutische bedrijven afbeelding 4 werkten aan de ontwikkeling van antistoffen die gebruikt kunnen worden als geneesmiddel tegen ebola. Een bedrijf ontwikkelde een cocktail die bestaat uit drie verschillende monoklonale antistoffen. Deze monoklonale antistoffen (mAb’s) zijn afkomstig van plasmacellen van een transgene muis die in het laboratorium gefuseerd waren met menselijke tumorcellen (afbeelding 4).$$, 'inline'),
  ('98178077-acd1-48da-bdcc-2c9a13af049d', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$celfusie van plasmacel en tumorcel bij de ontwikkeling van mAb''s$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context8.png$$,
   $$Bij de ontwikkeling werd een plasmacel van een muis gefuseerd met een tumorcel.$$, 'inline'),
  ('311756e2-025d-4761-83a5-1435f37605e6', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$ebolavaccin met toegevoegd viraal gen; eiwitten en genen van het ebolavirus (afbeelding 5)$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context9.png$$,
   $$In oktober 2019 werd het eerste vaccin tegen ebola goedgekeurd. Dit vaccin bestaat uit een verzwakt, ander type virus, waaraan een gen van het ebolavirus is toegevoegd. In afbeelding 5 zijn de verschillende eiwitten van het ebolavirus weergegeven, met daaronder de plaats van de bijbehorende genen op het genoom.
afbeelding 5
Legenda: NP gen voor eiwit NP dat het genoom beschermt VP... genen voor eiwitten VP24, VP30, VP35 en VP40 GP gen voor membraaneiwit GP L gen voor RNA-polymerase L$$, 'inline'),
  ('a821189a-c5f9-45cf-9674-241bbd42e6e6', '00d38e60-ceda-44aa-9ecb-8a384bdf7273', $$kenmerken van remdesivir, mAb''s en het vaccin$$,
   $$biologie-vwo-2023-ii-onderzoek-naar-medicijnen-tegen-ebola-context10.png$$,
   $$De drie methodes om ebola te bestrijden (remdesivir, mAb’s en het vaccin), hebben verschillende kenmerken. Enkele van deze kenmerken zijn:
1 De methode gebruikt kunstmatige passieve immunisatie.
2 De methode dient als behandeling van ebola-patiënten.
3 Een doel van de methode is dat er B-geheugencellen worden gevormd.$$, 'inline'),
  ('57077c77-4870-4d20-b1c0-910e3ba5fbf7', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$inleiding: Striga als parasitaire plant bij voedselgewassen$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context1.png$$,
   $$In grote delen van Afrika ten zuiden van de Sahara wordt de voedselproductie in toenemende mate bedreigd door parasitaire planten van het geslacht Striga. Door een infectie met Striga kan een gehele oogst verloren gaan. Meer kennis over deze parasiet kan helpen om maatregelen te treffen die het verlies aan opbrengst door Striga beperken.$$, 'inline'),
  ('58e88218-cd11-42e1-99c8-3eadcf2cdc6f', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$kieming van Striga-zaden alleen bij strigolactonen uit gastheerwortels (afbeelding 1)$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context2.png$$,
   $$Striga-soorten komen voornamelijk in Afrika en Azië voor. De planten hechten zich aan de wortels van voedselgewassen als mais, sorghum, gierst en rijst. Striga-planten produceren een grote hoeveelheid kleine zaden die wel tien jaar kiemkrachtig blijven. Zaden van Striga kiemen alleen in aanwezigheid van bepaalde hormonen – strigolactonen – die door de wortels van de gastheerplant worden uitgescheiden (afbeelding 1). De pijlen in afbeelding 1 geven de ontwikkeling van Striga aan.
afbeelding 1$$, 'inline'),
  ('72335872-3ad5-40cc-95fa-0d7891b5898f', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$strigolactonenproductie hangt af van fosfaatgehalte van de bodem$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context3.png$$,
   $$Planten zoals sorghum produceren strigolactonen en trekken daarmee mycorrhiza-schimmels aan. Zo kan een symbiose ontstaan waarvan beide organismen profiteren. De hoeveelheid strigolactonen die planten produceren, is afhankelijk van de hoeveelheid fosfaat in de bodem. Hoe armer de grond aan fosfaat, hoe meer strigolactonen worden geproduceerd. Striga-infectie vindt daardoor vooral plaats op voedselarme gronden.$$, 'inline'),
  ('20cd4b40-f5af-4683-9b9e-456c29363e42', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$uitspraken over de symbiose tussen mycorrhiza-schimmels en sorghum$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context4.png$$,
   $$Over de symbiose tussen mycorrhiza-schimmels en sorghum worden twee uitspraken gedaan:
1 Alleen water en zouten worden uitgewisseld.
2 De mycorrhiza-schimmels zijn in deze symbiose autotroof.$$, 'inline'),
  ('bb890fba-0d29-4a95-9c99-d8cea2620228', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$ondergrondse ontwikkelingsfase van het Striga-kiemplantje bij de gastheerplant$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context5.png$$,
   $$Het kiemplantje van Striga hecht zich aan de gastheerplant en ontwikkelt zich eerst vier tot zeven weken ondergronds. In deze fase verkrijgt het anorganische en organische stoffen van de gastheerplant.$$, 'inline'),
  ('ea4bde58-3716-4be0-8d71-b72614dfd5f5', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$organische stofoverdracht van gastheerplant naar Striga tijdens ondergrondse fase$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context6.png$$,
   $$Tijdens deze ontwikkeling is de hoeveelheid organische stoffen die door de gastheerplant wordt afgegeven, veel groter dan de netto toename ervan in Striga.$$, 'inline'),
  ('cb019067-c96b-42c5-8b75-97397647be10', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$watertransport tussen gastheerplant en Striga via geopende huidmondjes (afbeelding 2)$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context7.png$$,
   $$Na de eerste weken groeit Striga afbeelding 2 bovengronds verder. Bovengronds is Striga niet meer afhankelijk van de organische stoffen van de gastheer. Ondanks de meestal droge en warme omstandigheden op de akkers, staan de huidmondjes van Striga wijd open. In afbeelding 2 is met pijlen de richting van het watertransport door de gastheerplant en Striga schematisch weergegeven.$$, 'inline'),
  ('d5b793e0-4c6f-4438-8f7e-5a9d7e933e0b', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$ABA-PYL-PP2C-signaalcascade voor sluiten van huidmondjes; PP2C-mutatie in Striga (afbeelding 3)$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context8.png$$,
   $$Bij droogtestress produceren veel planten het hormoon abscisinezuur (ABA). In de sluitcellen van de huidmondjes bindt ABA aan de receptor PYL. Vervolgens bindt het eiwit PP2C aan het receptor-complex ABA- PYL, waardoor een signaalcascade in werking treedt die uiteindelijk leidt tot het sluiten van de huidmondjes (afbeelding 3).
afbeelding 3
Onderzoekers van Kobe University in Japan hebben mutaties in het PP2C-gen ontdekt, waardoor de ABA-signaalcascade in Striga niet in gang wordt gezet. Als gevolg hiervan blijven de huidmondjes altijd openstaan.$$, 'inline'),
  ('e3c626d0-9a83-4540-8c79-fb44bebdf378', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$mechanische bestrijding (wieden) als enige beschikbare methode tegen Striga$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context9.png$$,
   $$Het inzicht van de Japanse onderzoekers kan op termijn leiden tot een manier om Striga te bestrijden. Voorlopig is echter in grote delen van Afrika mechanische bestrijding (onkruid wieden) de enige manier om groei van Striga enigszins tegen te gaan.$$, 'inline'),
  ('6543e812-7969-4631-b4de-66fe18ff345a', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$jaarlijks zaaien van vlinderbloemigen vermindert Striga en verhoogt sorghumopbrengst$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context10.png$$,
   $$Een veelgebruikte manier om Striga-infectie te voorkomen is het jaarlijks zaaien van vlinderbloemige gewassen. Op akkers met sorghum waarop ook vlinderbloemigen groeien, komt minder Striga voor. Waardoor dit komt is onbekend, mogelijk zijn de omstandigheden voor Striga ongunstig door de aanwezigheid van vlinderbloemigen.
Door het jaarlijks zaaien van vlinderbloemigen groeit er minder Striga, waardoor de opbrengst van sorghum hoger is.$$, 'inline'),
  ('7390e833-9fbc-4e49-80e8-b9836f690646', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$veldexperiment naar effect van vlinderbloemigen op netto primaire productie van sorghum$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context11.png$$,
   $$Onderzoekers willen door middel van een veld-experiment bepalen in hoeverre het jaarlijks zaaien van vlinderbloemigen de netto primaire productie van sorghum beïnvloedt.$$, 'inline'),
  ('0faa9bdc-6e16-45f4-a212-b6f8accfa1ec', '5e18ab1f-b7c9-4642-a32c-e6436f1495a7', $$strategieën P en Q tegen Striga-infectie en mogelijke maatregelen$$,
   $$biologie-vwo-2023-ii-strijden-tegen-striga-context12.png$$,
   $$Wetenschappers menen dat er een combinatie van strategieën ingezet moet worden om Striga-infecties te voorkomen of onder controle te krijgen. Er wordt onderzoek gedaan naar twee strategieën: strategie P: kieming van Striga-zaden remmen of voorkomen strategie Q: Striga-zaden voortijdig laten ontkiemen
Mogelijke maatregelen hierbij zijn:
1 Fosfaat-houdende meststoffen op het land brengen.
2 Meerdere seizoenen gewassen inzaaien die kieming van Striga-zaden stimuleren, maar die zelf niet geparasiteerd worden.
3 Stoffen in de grond brengen die dezelfde werking hebben als strigolactonen voorafgaande aan het zaaien van het voedingsgewas.$$, 'inline'),
  ('ce9d32d6-19d4-4e9f-8ef0-d8d3b4923b26', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$inleiding: sikkelcelanemie als erfelijke bloedziekte$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context1.png$$,
   $$Sikkelcelanemie is een erfelijke bloedziekte, waarbij afwijkend hemoglobine wordt aangemaakt. De normale vorm van rode bloedcellen kan daardoor veranderen in een sikkelvorm. Wereldwijd wordt onderzoek gedaan naar nieuwe behandelingen voor deze ziekte.$$, 'inline'),
  ('bff5824f-912a-4f09-9b35-a5ff02e49fb9', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$puntmutatie in het β-globinegen en normaal hemoglobine (afbeelding 1)$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context2.png$$,
   $$Hemoglobine bestaat uit twee α- en twee β-globineketens. Sikkelcelanemie wordt veroorzaakt door een puntmutatie in het gen dat codeert voor de β-globineketen. In een van de tripletten is een A vervangen door een T, en als gevolg hiervan is in de β-globine-keten glutaminezuur vervangen door valine. De ziekte ontstaat alleen als deze mutatie in beide allelen voor β-globine aanwezig is. In afbeelding 1 is normaal hemoglobine weergegeven.
afbeelding 1$$, 'inline'),
  ('351237d2-cebd-4be1-9654-ac3ba68505c3', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$uitspraken over de mutatie in het β-globinegen en de gevolgen ervan$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context3.png$$,
   $$Over de mutatie in het β-globine-gen en gevolgen ervan worden de volgende uitspraken gedaan:
1 De mutatie kan in een intron hebben plaatsgevonden.
2 De mutatie veroorzaakt een verschuiving van het leesraam.
3 Van de β-globineketen is de primaire structuur veranderd.$$, 'inline'),
  ('0b30dae2-428a-46cc-9eae-a661c5fce7cd', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$sikkelvorming, hemolyse en vaatverstopping bij sikkelcelanemie$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context4.png$$,
   $$Bij sikkelcelanemie vormen de afwijkende β-globineketens – na afgifte van zuurstof – lange vezels die zich hechten aan de celmembraan van de rode bloedcel. Dit veroorzaakt de typische sikkelvorm. Door deze vormverandering gaat de rode bloedcel sneller kapot (hemolyse). Bij mensen met sikkelcelanemie is de gemiddelde levensduur van een rode bloedcel daardoor slechts 20 dagen in plaats van 120 dagen. Ook is er een verhoogde activiteit van witte bloedcellen en worden er bloedplaatjes geactiveerd. Daardoor ontstaat een ontstekingsreactie in het endotheel van de bloedvaten. De verstoppingen die hierdoor kunnen ontstaan, veroorzaken zuurstofgebrek in botten en organen. Dit leidt tot pijn en beschadiging van organen.
In de bloedvaten van de longen kan ook door een lage zuurstofspanning vaatverstopping optreden, waardoor de bloeddruk in die vaten stijgt. Dit kan leiden tot verwijding van één van de hartkamers.$$, 'inline'),
  ('c8314527-1e92-42e4-94ce-5988864f7fea', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$galstenen en verstopping van de galbuis bij sikkelcelanemie$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context5.png$$,
   $$Bij mensen met sikkelcelanemie komen vaak galstenen voor. Galstenen ontstaan in de galblaas door een verhoogde concentratie van de stof bilirubine, die vrijkomt bij de afbraak van rode bloedcellen. Galstenen leiden tot problemen als ze de galblaas verlaten en de galbuis blokkeren. Deze blokkade kan leiden tot een ontsteking van de lever en tot problemen met de spijsvertering.$$, 'inline'),
  ('e48d55d3-1478-4d24-b7ef-79e9926f23c2', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$behandeling met pijnbestrijding en bloedtransfusies; uitspraken over het effect van bloedtransfusies$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context6.png$$,
   $$De behandeling van sikkelcelanemie bestaat voornamelijk uit pijnbestrijding en herhaaldelijke bloedtransfusies. Over het effect van bloedtransfusies worden de volgende uitspraken gedaan:
1 De bloedtransfusie gaat tijdelijk een tekort aan rode bloedcellen tegen.
2 Het aandeel sikkelcellen neemt in de weken na een bloedtransfusie geleidelijk af.$$, 'inline'),
  ('b51b9b7f-52d4-4e38-8e4b-7375bf5700f6', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$hydroxycarbamide en foetaal hemoglobine; uitspraken over hydroxycarbamide$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context7.png$$,
   $$Een van de medicijnen tegen sikkelcelanemie is hydroxycarbamide. Dit medicijn remt de productie van de witte bloedcellen en bloedplaatjes, en verhoogt de productie van foetaal hemoglobine. Foetaal hemoglobine heeft een grotere affiniteit voor zuurstof dan adult hemoglobine en heeft twee γ-globineketens in plaats van twee β-globineketens. Normaal neemt de expressie van het gen voor γ-globine na de geboorte af.
Over hydroxycarbamide worden de volgende uitspraken gedaan:
1 Het is werkzaam in het rode beenmerg.
2 Door gebruik ervan treedt minder sikkelcelvorming op.
3 Door gebruik ervan wordt het ontstaan van ontstekingen in het endotheel van bloedvaten onderdrukt.$$, 'inline'),
  ('b634c913-4fbf-4b6f-8c57-d6a9916f2bfc', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$het medicijn voxelotor verhoogt de zuurstofaffiniteit van hemoglobine$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context8.png$$,
   $$Recent is een nieuw medicijn (voxelotor) goedgekeurd dat specifiek bindt aan de α-globineketen van hemoglobine waardoor de affiniteit van hemoglobine voor zuurstof groter wordt.$$, 'inline'),
  ('635b9c03-718e-4e04-a1cf-3b827f65f69e', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$gentherapie met CRISPR-Cas op eigen beenmergcellen voorkomt afweerreactie$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context9.png$$,
   $$Om sikkelcelanemie blijvend te genezen ontwikkelden onderzoekers van Harvard University een gentherapie. Ze isoleerden beenmergcellen van een patiënt en modificeerden die met de CRISPR-Cas-techniek, zodat de expressie van het BCL11A-gen in deze cellen werd verminderd. Het BCL11A-eiwit reguleert de expressie van de globinegenen. Nadat de achtergebleven beenmergcellen van de patiënt waren gedood, werden de gemodificeerde beenmergcellen terug in het lichaam gebracht.
Het terugplaatsen van de eigen gemodificeerde beenmergcellen heeft als voordeel dat de kans op het ontstaan van een specifieke afweerreactie veel kleiner is dan bij het injecteren van beenmergcellen van een donor. Bij een specifieke afweerreactie tegen beenmergcellen van een donor zijn een bepaald type T-cellen betrokken.$$, 'inline'),
  ('be9c9dd2-7f77-46d3-bafa-9fa52acdff57', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$BCL11A-gen reguleert globine-expressie; effect van CRISPR-Cas-bewerking (afbeelding 2)$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context10.png$$,
   $$In afbeelding 2 is het BCL11A-gen op chromosoom 2 weergegeven: de grijze blokjes zijn de exons; deel P is een regulerende sequentie van dit gen. Ook is weergegeven hoe het BCL11A-eiwit de expressie van de globinegenen op chromosoom 11 reguleert. LCR is de regulerende sequentie van de globinegenen. De linkerkant van de afbeelding toont de situatie in de beenmergcellen van een patiënt met sikkelcelanemie. De rechterkant toont de situatie in beenmergcellen waarbij met de CRISPR- Cas-techniek de regulerende sequentie van het BCL11A-gen is bewerkt.
afbeelding 2$$, 'inline'),
  ('65cf9df9-0f90-42fa-9f37-1dcb2dda43e0', 'ab3247d0-8b42-44c6-aadb-5ca157c00b7d', $$vergelijking met cellen waarin het BCL11A-gen volledig is uitgeschakeld$$,
   $$biologie-vwo-2023-ii-nieuwe-behandelmethodes-voor-sikkelcelanemie-context11.png$$,
   $$Met de CRISPR-Cas-techniek werd de expressie van het BCL11A-gen verminderd. In het beschreven onderzoek gebruikten de wetenschappers ter vergelijking ook cellen waarvan het BCL11A-gen volledig was uitgeschakeld.$$, 'inline'),
  ('08292ed5-b3b1-4f9d-b89b-3ab5676a655b', '49823ab6-d5b0-45d9-ab1a-059f0890861d', $$inleiding: onderzoek naar dopinggebruik via rioolwater$$,
   $$biologie-vwo-2023-ii-doping-in-rioolwater-context1.png$$,
   $$Op verzoek van het World Anti-Doping Agency (WADA) hebben wetenschappers van de Universiteit van Amsterdam onderzoek gedaan naar dopinggebruik in de sport. Zij analyseerden het rioolwater in drie Nederlandse steden voor, tijdens en na een groot sportevenement.$$, 'inline'),
  ('129ff5cd-2aec-4d04-8b9d-7a76f04bb7de', '49823ab6-d5b0-45d9-ab1a-059f0890861d', $$opzet van het rioolwateronderzoek in drie steden; resultaten voor efedrine, norefedrine, DMAA en DNP (afbeelding 1)$$,
   $$biologie-vwo-2023-ii-doping-in-rioolwater-context2.png$$,
   $$De concentratie van doping in rioolwater van een stad is een goede maat voor het gebruik van doping in die stad. In drie steden werd twee weken lang, dagelijks, meerdere keren per uur, een beetje rioolwater verzameld. Op de zaterdag van het eerste weekend van de onderzoeksperiode begon in elke stad een groot sportevenement:
− in stad P, een grote stad, een atletiekevenement van vijf dagen voor professionele sporters
− in stad Q, een middelgrote stad, een tweedaags bodybuilding- evenement voor amateurs
− in stad R, een kleine stad, een eendaags bodybuildingevenement voor amateurs Het rioolwater werd in het laboratorium getest op verschillende stoffen. Afbeelding 1 toont de resultaten voor efedrine, norefedrine, DMAA (methylhexanamine) en DNP (2,4-dinitrofenol).
afbeelding 1$$, 'inline'),
  ('6f1ac9b6-aeb1-4c18-9634-27d15df1b1e2', '49823ab6-d5b0-45d9-ab1a-059f0890861d', $$werking van efedrine, norefedrine, DMAA en DNP; tweede weekend als controleperiode$$,
   $$biologie-vwo-2023-ii-doping-in-rioolwater-context3.png$$,
   $$Efedrine, norefedrine en DMAA zijn voor sporters verboden om te gebruiken. De werking van deze stoffen komt overeen met die van (nor)adrenaline, maar met een sterker effect. Norefedrine ontstaat ook als afbraakproduct na het gebruik van amfetamine, een harddrug. DNP wordt gebruikt om af te vallen. De stof is verboden voor consumptie. Efedrine, norefedrine, DMAA en DNP worden snel uitgescheiden, en komen via urine in het rioolwater terecht.
De onderzoeksperiode besloeg twee weken (afbeelding 1). Bij een dergelijk onderzoek kan geen controlegroep worden gemaakt. Als controle worden daarom de metingen uit het tweede weekend van de onderzoeksperiode gebruikt.$$, 'inline'),
  ('6933a8b0-696f-4872-99de-e8d6107939c7', '49823ab6-d5b0-45d9-ab1a-059f0890861d', $$drie uitspraken over het rioolonderzoek en de resultaten ervan$$,
   $$biologie-vwo-2023-ii-doping-in-rioolwater-context4.png$$,
   $$Over het rioolonderzoek en het resultaat ervan worden drie uitspraken gedaan:
1 De geteste middelen worden gebruikt door professionele atleten tijdens het evenement in stad P.
2 In stad P is het drugsgebruik per inwoner gemiddeld groter dan in stad R.
3 De maximale concentratie DNP in het rioolwater tijdens het evenement in stad Q is meer dan 20 keer zo hoog als normaal.$$, 'inline'),
  ('51a5f5a7-0749-43fa-9278-d66e6aaa87fd', '49823ab6-d5b0-45d9-ab1a-059f0890861d', $$werking van DMAA via (nor)adrenaline-receptoren; effecten van doping$$,
   $$biologie-vwo-2023-ii-doping-in-rioolwater-context5.png$$,
   $$DMAA is een synthetische drug die door sommige sporters wordt gebruikt voor prestatieverbetering. DMAA heeft echter veel negatieve bijwerkingen, soms zelfs met dodelijke afloop. DMAA heeft eenzelfde werking als (nor)adrenaline en koppelt aan dezelfde receptoren, maar blijft daar langer aan gebonden.
Sporters gebruiken doping om verschillende effecten te bereiken, zoals:
1 verwijding van de bronchiolen
2 vergroting van de alertheid
3 toename van de spiermassa$$, 'inline'),
  ('9a4c15ec-4b14-4c17-bfbc-68ce328a0340', '49823ab6-d5b0-45d9-ab1a-059f0890861d', $$DNP ontkoppelt de protonengradiënt in mitochondriën (afbeelding 2)$$,
   $$biologie-vwo-2023-ii-doping-in-rioolwater-context6.png$$,
   $$Het meest verontrustend was de vondst van DNP in het rioolwater. Gebruik van DNP kan namelijk ernstige gevolgen hebben voor de sporter. Deze stof bindt H⁺-ionen in de intermembraanruimte, tussen de binnenmembraan en de buitenmembraan van de mitochondriën, en transporteert ze vervolgens door de binnenmembraan (afbeelding 2). Als gevolg hiervan wordt de synthese van ATP sterk verminderd.
afbeelding 2$$, 'inline'),
  ('20348b64-5acd-47b9-a00a-44131308f9a6', '49823ab6-d5b0-45d9-ab1a-059f0890861d', $$gebruik van DNP door bodybuilders om lichaamsvet te verminderen$$,
   $$biologie-vwo-2023-ii-doping-in-rioolwater-context7.png$$,
   $$Sommige bodybuilders gebruiken DNP om hun hoeveelheid lichaamsvet te verminderen.$$, 'inline'),
  ('8c0a787a-205e-49e3-b773-6e7ca01b76ff', '49823ab6-d5b0-45d9-ab1a-059f0890861d', $$gebruik van DNP kan de lichaamstemperatuur gevaarlijk verhogen$$,
   $$biologie-vwo-2023-ii-doping-in-rioolwater-context8.png$$,
   $$Bij gebruik van DNP kan de lichaamstemperatuur oplopen tot boven
42 °C. Dit heeft geleid tot dodelijke slachtoffers.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('32782875-a685-4d88-874a-76b708bd278c', '209d0465-d258-4898-9f17-db0c7d19458d', 1,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Reproductie van het organisme"}]'::jsonb,
   '["allel", "genotype-fenotype", "dominant", "dihybride kruising"]'::jsonb,
