   $$biologie-vwo-2023-ii-vraag3.png$$, $$2p 3 Schrijf de nummers 1, 2 en 3 onder elkaar en noteer erachter of de betreffende uitspraak juist of onjuist is.$$, array['ed841d18-35c0-4b23-a002-5e503d237140', '530fb7cb-a58a-4676-87f2-53b2978a0ce1']::uuid[]),
  ('4c55afdc-f505-4b55-ba9c-4f68f58f14b8', '209d0465-d258-4898-9f17-db0c7d19458d', 4,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Selectie"}]'::jsonb,
